-- Approved WFS floor-plan layout normalized to a 1600 x 900 logical board.
-- Coordinates are traced from public/reference/warehouse-floor-plan.png.
values ('10000000-0000-0000-0000-000000000001', 'WFS Warehouse', 'WFS-01')
on conflict (id) do update set name = excluded.name, code = excluded.code;

on conflict (id) do update set
  name = excluded.name, zone_type = excluded.zone_type, capacity = excluded.capacity,
  x = excluded.x, y = excluded.y, width = excluded.width, height = excluded.height, is_active = true;

on conflict (id) do update set
  zone_id = excluded.zone_id, slot_number = excluded.slot_number, x = excluded.x, y = excluded.y,
  default_orientation_degrees = excluded.default_orientation_degrees, is_active = true;

values ('10000000-0000-0000-0000-000000000001', 'departure_cleanup_seconds', '120'::jsonb)
on conflict (warehouse_id, key) do update set value = excluded.value;
